import 'dart:convert';
import 'package:flutter/material.dart';
import '../models/deck_model.dart';

class CodeExportGenerator {
  /// 1. Recursive Flutter Widget code generation (with complete children tree & AutoLayout)
  static String generateFlutterCode(DeckElement elem) {
    final componentName = _toPascalCase(elem.name);
    final innerWidgetCode = _generateFlutterElementBody(elem, indent: 6);

    return '''
// Flutter Component: $componentName
// Generated by DeckStudio (Hierarchical Component Tree Export)
import 'package:flutter/material.dart';

class ${componentName}Component extends StatelessWidget {
  const ${componentName}Component({super.key});

  @override
  Widget build(BuildContext context) {
    return Positioned(
      left: ${elem.x.toStringAsFixed(1)},
      top: ${elem.y.toStringAsFixed(1)},
      width: ${elem.width.toStringAsFixed(1)},
      height: ${elem.height.toStringAsFixed(1)},
      child: $innerWidgetCode,
    );
  }
}
''';
  }

  static String _generateFlutterElementBody(DeckElement elem, {int indent = 0}) {
    final sp = ' ' * indent;
    final ts = elem.textStyle;
    final bs = elem.boxStyle;
    final textHex = '0x${ts.color.toARGB32().toRadixString(16).padLeft(8, '0').toUpperCase()}';
    final bgHex = '0x${bs.backgroundColor.toARGB32().toRadixString(16).padLeft(8, '0').toUpperCase()}';
    final borderHex = '0x${bs.borderColor.toARGB32().toRadixString(16).padLeft(8, '0').toUpperCase()}';

    // If it has children (Frame / AutoLayout / Group)
    if (elem.children.isNotEmpty) {
      final childrenWidgets = elem.children
          .map((child) => _generateFlutterElementBody(child, indent: indent + 4))
          .join(',\n');

      if (elem.autoLayoutDirection == AutoLayoutDirection.horizontal) {
        return '''Container(
$sp  padding: const EdgeInsets.all(${elem.autoLayoutPadding.toStringAsFixed(1)}),
$sp  decoration: BoxDecoration(
$sp    color: const Color($bgHex),
$sp    borderRadius: BorderRadius.circular(${bs.borderRadius.toStringAsFixed(1)}),
$sp    border: Border.all(color: const Color($borderHex), width: ${bs.borderWidth.toStringAsFixed(1)}),
$sp  ),
$sp  child: Row(
$sp    mainAxisSize: MainAxisSize.min,
$sp    spacing: ${elem.autoLayoutSpacing.toStringAsFixed(1)},
$sp    children: [
$childrenWidgets,
$sp    ],
$sp  ),
$sp)''';
      } else if (elem.autoLayoutDirection == AutoLayoutDirection.vertical) {
        return '''Container(
$sp  padding: const EdgeInsets.all(${elem.autoLayoutPadding.toStringAsFixed(1)}),
$sp  decoration: BoxDecoration(
$sp    color: const Color($bgHex),
$sp    borderRadius: BorderRadius.circular(${bs.borderRadius.toStringAsFixed(1)}),
$sp    border: Border.all(color: const Color($borderHex), width: ${bs.borderWidth.toStringAsFixed(1)}),
$sp  ),
$sp  child: Column(
$sp    mainAxisSize: MainAxisSize.min,
$sp    crossAxisAlignment: CrossAxisAlignment.start,
$sp    spacing: ${elem.autoLayoutSpacing.toStringAsFixed(1)},
$sp    children: [
$childrenWidgets,
$sp    ],
$sp  ),
$sp)''';
      } else {
        // Stack-based absolute children
        final stackChildren = elem.children.map((child) {
          final childBody = _generateFlutterElementBody(child, indent: indent + 6);
          return '''$sp    Positioned(
$sp      left: ${child.x.toStringAsFixed(1)},
$sp      top: ${child.y.toStringAsFixed(1)},
$sp      width: ${child.width.toStringAsFixed(1)},
$sp      height: ${child.height.toStringAsFixed(1)},
$sp      child: $childBody,
$sp    )''';
        }).join(',\n');

        return '''Container(
$sp  decoration: BoxDecoration(
$sp    color: const Color($bgHex),
$sp    borderRadius: BorderRadius.circular(${bs.borderRadius.toStringAsFixed(1)}),
$sp    border: Border.all(color: const Color($borderHex), width: ${bs.borderWidth.toStringAsFixed(1)}),
$sp  ),
$sp  child: Stack(
$sp    children: [
$stackChildren,
$sp    ],
$sp  ),
$sp)''';
      }
    }

    // Leaf Text Element
    if (elem.type == ElementType.text) {
      final textContent = elem.props['title'] ?? elem.props['titleBlack'] ?? elem.name;
      final escaped = textContent.replaceAll('"', '\\"').replaceAll('\n', '\\n');
      return '''Text(
$sp  "$escaped",
$sp  textAlign: TextAlign.${ts.textAlign.name},
$sp  style: TextStyle(
$sp    fontFamily: '${ts.fontFamily}',
$sp    fontSize: ${ts.fontSize.toStringAsFixed(1)},
$sp    fontWeight: FontWeight.w${_weightToNumber(ts.fontWeight)},
$sp    color: const Color($textHex),
$sp    letterSpacing: ${ts.letterSpacing.toStringAsFixed(2)},
$sp    height: ${ts.height.toStringAsFixed(2)},
$sp    wordSpacing: ${ts.wordSpacing.toStringAsFixed(2)},
$sp  ),
$sp)''';
    }

    // Leaf Badge Element
    if (elem.type == ElementType.badge) {
      final textContent = elem.props['title'] ?? elem.props['tag'] ?? elem.props['num'] ?? elem.props['badge'] ?? elem.name;
      final escaped = textContent.replaceAll('"', '\\"').replaceAll('\n', '\\n');
      return '''Container(
$sp  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
$sp  decoration: BoxDecoration(
$sp    color: const Color($bgHex),
$sp    borderRadius: BorderRadius.circular(${bs.borderRadius > 0 ? bs.borderRadius.toStringAsFixed(1) : '6.0'}),
$sp    border: Border.all(color: const Color($borderHex), width: ${bs.borderWidth.toStringAsFixed(1)}),
$sp  ),
$sp  child: Text(
$sp    "$escaped",
$sp    style: TextStyle(
$sp      fontFamily: '${ts.fontFamily}',
$sp      fontSize: ${ts.fontSize.toStringAsFixed(1)},
$sp      fontWeight: FontWeight.w${_weightToNumber(ts.fontWeight)},
$sp      color: const Color($textHex),
$sp    ),
$sp  ),
$sp)''';
    }

    // Leaf Shape / Container
    final titleText = elem.props['title'] ?? elem.name;
    final escapedTitle = titleText.replaceAll('"', '\\"').replaceAll('\n', '\\n');
    return '''Container(
$sp  padding: const EdgeInsets.all(${bs.padding.toStringAsFixed(1)}),
$sp  decoration: BoxDecoration(
$sp    color: const Color($bgHex),
$sp    borderRadius: BorderRadius.circular(${bs.borderRadius.toStringAsFixed(1)}),
$sp    border: Border.all(color: const Color($borderHex), width: ${bs.borderWidth.toStringAsFixed(1)}),
$sp    ${bs.hasShadow ? 'boxShadow: const [BoxShadow(color: Color(0x0A0F172A), blurRadius: 16, offset: Offset(0, 4))],' : ''}
$sp  ),
$sp  child: Text(
$sp    "$escapedTitle",
$sp    style: TextStyle(
$sp      fontFamily: '${ts.fontFamily}',
$sp      fontSize: ${ts.fontSize.toStringAsFixed(1)},
$sp      fontWeight: FontWeight.w${_weightToNumber(ts.fontWeight)},
$sp      color: const Color($textHex),
$sp    ),
$sp  ),
$sp)''';
  }

  /// 2. Recursive HTML / Tailwind CSS generation (with complete hierarchy)
  static String generateHtmlCode(DeckElement elem) {
    final body = _generateHtmlElementBody(elem, indent: 2);
    return '''<!-- ======================================================== -->
<!-- HTML / TAILWIND HIERARCHICAL COMPONENT: ${elem.name} -->
<!-- ======================================================== -->
<div class="relative" style="width: ${elem.width}px; height: ${elem.height}px;">
$body
</div>
''';
  }

  static String _generateHtmlElementBody(DeckElement elem, {int indent = 0}) {
    final sp = ' ' * indent;
    final ts = elem.textStyle;
    final bs = elem.boxStyle;
    final textHex = _colorToHex(ts.color);
    final bgHex = _colorToHex(bs.backgroundColor);
    final borderHex = _colorToHex(bs.borderColor);

    if (elem.children.isNotEmpty) {
      final childrenHtml = elem.children
          .map((c) => _generateHtmlElementBody(c, indent: indent + 2))
          .join('\n');

      if (elem.autoLayoutDirection == AutoLayoutDirection.horizontal) {
        return '''$sp<div class="flex flex-row items-center"
$sp     style="gap: ${elem.autoLayoutSpacing}px; padding: ${elem.autoLayoutPadding}px; background-color: $bgHex; border-radius: ${bs.borderRadius}px; border: ${bs.borderWidth}px solid $borderHex;">
$childrenHtml
$sp</div>''';
      } else if (elem.autoLayoutDirection == AutoLayoutDirection.vertical) {
        return '''$sp<div class="flex flex-col items-start"
$sp     style="gap: ${elem.autoLayoutSpacing}px; padding: ${elem.autoLayoutPadding}px; background-color: $bgHex; border-radius: ${bs.borderRadius}px; border: ${bs.borderWidth}px solid $borderHex;">
$childrenHtml
$sp</div>''';
      } else {
        return '''$sp<div class="relative"
$sp     style="width: ${elem.width}px; height: ${elem.height}px; background-color: $bgHex; border-radius: ${bs.borderRadius}px; border: ${bs.borderWidth}px solid $borderHex;">
$childrenHtml
$sp</div>''';
      }
    }

    if (elem.type == ElementType.text) {
      final textContent = elem.props['title'] ?? elem.props['titleBlack'] ?? elem.name;
      return '''$sp<div style="font-family: '${ts.fontFamily}', sans-serif; font-size: ${ts.fontSize}px; font-weight: ${_weightToNumber(ts.fontWeight)}; color: $textHex; letter-spacing: ${ts.letterSpacing}px; line-height: ${ts.height}; word-spacing: ${ts.wordSpacing}px; text-align: ${ts.textAlign.name};">
$sp  $textContent
$sp</div>''';
    }

    if (elem.type == ElementType.badge) {
      final textContent = elem.props['title'] ?? elem.props['tag'] ?? elem.props['num'] ?? elem.props['badge'] ?? elem.name;
      return '''$sp<span class="inline-block"
$sp      style="padding: 4px 10px; background-color: $bgHex; border-radius: ${bs.borderRadius > 0 ? bs.borderRadius : 6}px; border: ${bs.borderWidth}px solid $borderHex; font-family: '${ts.fontFamily}'; font-size: ${ts.fontSize}px; font-weight: ${_weightToNumber(ts.fontWeight)}; color: $textHex;">
$sp  $textContent
$sp</span>''';
    }

    final title = elem.props['title'] ?? elem.name;
    return '''$sp<div style="padding: ${bs.padding}px; background-color: $bgHex; border-radius: ${bs.borderRadius}px; border: ${bs.borderWidth}px solid $borderHex; font-family: '${ts.fontFamily}'; font-size: ${ts.fontSize}px; color: $textHex;">
$sp  $title
$sp</div>''';
  }

  /// 3. Recursive Figma Design Tokens & Component JSON Spec
  static String generateFigmaSpec(DeckElement elem) {
    final figmaNodeTree = _elemToFigmaNode(elem);
    final prettyJson = const JsonEncoder.withIndent('  ').convert(figmaNodeTree);

    final ts = elem.textStyle;
    final bs = elem.boxStyle;
    final textHex = _colorToHex(ts.color);
    final bgHex = _colorToHex(bs.backgroundColor);
    final borderHex = _colorToHex(bs.borderColor);

    return '''/* ======================================================== */
/* FIGMA AUTO-LAYOUT HIERARCHICAL COMPONENT SPEC            */
/* Includes complete nested children tree & AutoLayout spec */
/* ======================================================== */

/* Top Container Geometry */
width: ${elem.width}px;
height: ${elem.height}px;
position: absolute;
left: ${elem.x}px;
top: ${elem.y}px;
padding: ${elem.autoLayoutPadding > 0 ? elem.autoLayoutPadding : bs.padding}px;
border-radius: ${bs.borderRadius}px;
border: ${bs.borderWidth}px solid $borderHex;
background: $bgHex;

/* AutoLayout Flow */
layout-mode: ${elem.autoLayoutDirection == AutoLayoutDirection.horizontal ? 'HORIZONTAL' : (elem.autoLayoutDirection == AutoLayoutDirection.vertical ? 'VERTICAL' : 'NONE')};
item-spacing: ${elem.autoLayoutSpacing}px;
sub-elements-count: ${elem.children.length};

/* Top Typography */
font-family: "${ts.fontFamily}";
font-size: ${ts.fontSize}px;
font-weight: ${_weightToNumber(ts.fontWeight)};
color: $textHex;
letter-spacing: ${ts.letterSpacing}px;
line-height: ${(ts.fontSize * ts.height).toStringAsFixed(1)}px;

/* ======================================================== */
/* FIGMA COMPONENT TREE JSON (Copy & Paste / Tokens Studio) */
/* ======================================================== */
$prettyJson
''';
  }

  static Map<String, dynamic> _elemToFigmaNode(DeckElement elem) {
    final ts = elem.textStyle;
    final bs = elem.boxStyle;
    final textHex = _colorToHex(ts.color);
    final bgHex = _colorToHex(bs.backgroundColor);
    final borderHex = _colorToHex(bs.borderColor);

    final isFrame = elem.children.isNotEmpty || elem.type == ElementType.group;
    final isText = elem.type == ElementType.text;

    final node = <String, dynamic>{
      'id': elem.id,
      'name': elem.name,
      'type': isText ? 'TEXT' : (isFrame ? 'FRAME' : 'RECTANGLE'),
      'x': elem.x,
      'y': elem.y,
      'width': elem.width,
      'height': elem.height,
    };

    if (isFrame) {
      node['layoutMode'] = elem.autoLayoutDirection == AutoLayoutDirection.horizontal
          ? 'HORIZONTAL'
          : (elem.autoLayoutDirection == AutoLayoutDirection.vertical ? 'VERTICAL' : 'NONE');
      node['itemSpacing'] = elem.autoLayoutSpacing;
      node['padding'] = elem.autoLayoutPadding > 0 ? elem.autoLayoutPadding : bs.padding;
      node['primaryAxisAlignItems'] = 'MIN';
      node['counterAxisAlignItems'] = 'CENTER';
      node['cornerRadius'] = bs.borderRadius;
      node['fills'] = [
        {'type': 'SOLID', 'color': _colorToRgbMap(bs.backgroundColor), 'hex': bgHex}
      ];
      if (bs.borderWidth > 0) {
        node['strokes'] = [
          {'type': 'SOLID', 'color': _colorToRgbMap(bs.borderColor), 'hex': borderHex}
        ];
        node['strokeWeight'] = bs.borderWidth;
      }
      node['children'] = elem.children.map((c) => _elemToFigmaNode(c)).toList();
    } else if (isText) {
      final characters = elem.props['title'] ?? elem.props['titleBlack'] ?? elem.name;
      node['characters'] = characters;
      node['style'] = {
        'fontFamily': ts.fontFamily,
        'fontSize': ts.fontSize,
        'fontWeight': _weightToNumber(ts.fontWeight),
        'letterSpacing': ts.letterSpacing,
        'lineHeightPx': ts.fontSize * ts.height,
        'wordSpacing': ts.wordSpacing,
        'textAlignHorizontal': ts.textAlign.name.toUpperCase(),
      };
      node['fills'] = [
        {'type': 'SOLID', 'color': _colorToRgbMap(ts.color), 'hex': textHex}
      ];
    } else {
      // Shape / Badge / Other
      final characters = elem.props['title'] ?? elem.props['tag'] ?? elem.props['badge'] ?? elem.name;
      node['characters'] = characters;
      node['cornerRadius'] = bs.borderRadius;
      node['fills'] = [
        {'type': 'SOLID', 'color': _colorToRgbMap(bs.backgroundColor), 'hex': bgHex}
      ];
      if (bs.borderWidth > 0) {
        node['strokes'] = [
          {'type': 'SOLID', 'color': _colorToRgbMap(bs.borderColor), 'hex': borderHex}
        ];
        node['strokeWeight'] = bs.borderWidth;
      }
      node['style'] = {
        'fontFamily': ts.fontFamily,
        'fontSize': ts.fontSize,
        'fontWeight': _weightToNumber(ts.fontWeight),
        'letterSpacing': ts.letterSpacing,
        'color': textHex,
      };
    }

    return node;
  }

  static Map<String, double> _colorToRgbMap(Color color) {
    return {
      'r': double.parse((color.r).toStringAsFixed(3)),
      'g': double.parse((color.g).toStringAsFixed(3)),
      'b': double.parse((color.b).toStringAsFixed(3)),
      'a': double.parse((color.a).toStringAsFixed(3)),
    };
  }

  static String _colorToHex(Color color) {
    final r = (color.r * 255).toInt().toRadixString(16).padLeft(2, '0');
    final g = (color.g * 255).toInt().toRadixString(16).padLeft(2, '0');
    final b = (color.b * 255).toInt().toRadixString(16).padLeft(2, '0');
    return '#$r$g$b'.toUpperCase();
  }

  static String _toPascalCase(String text) {
    final cleaned = text
        .replaceAll(RegExp(r'[^a-zA-Z0-9가-힣]'), ' ')
        .split(' ')
        .where((s) => s.isNotEmpty)
        .map((s) => s[0].toUpperCase() + s.substring(1))
        .join('');
    return cleaned.isEmpty ? 'Component' : cleaned;
  }

  static int _weightToNumber(FontWeight weight) {
    switch (weight) {
      case FontWeight.w100: return 100;
      case FontWeight.w200: return 200;
      case FontWeight.w300: return 300;
      case FontWeight.w400: return 400;
      case FontWeight.w500: return 500;
      case FontWeight.w600: return 600;
      case FontWeight.w700: return 700;
      case FontWeight.w800: return 800;
      case FontWeight.w900: return 900;
      default: return 400;
    }
  }
}
